1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	import org.springframework.samples.petclinic.util.E164PhoneNumbers;
12	
13	import java.time.LocalDate;
14	import java.time.Month;
15	import java.time.Period;
16	import java.util.Collection;
17	import java.util.List;
18	import java.util.Map;
19	
20	/**
21	 * Maps Owner & OwnerDto using Mapstruct
22	 */
23	@Mapper(uses = PetMapper.class)
24	public interface OwnerMapper {
25	
26	    @Mapping(target = "displayName",
27	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
28	    @Mapping(target = "initials",
29	        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" "
30	            + "+ owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
31	    @Mapping(target = "membershipPoints",
32	        expression = "java(toMembershipPoints(owner))")
33	    @Mapping(target = "membershipLevel",
34	        expression = "java(toMembershipLevel(owner))")
35	    @Mapping(target = "locality",
36	        expression = "java(toLocality(owner))")
37	    @Mapping(target = "timezone",
38	        expression = "java(toTimezone(owner))")
39	    @Mapping(target = "contactPreference",
40	        expression = "java(toContactPreference(owner))")
41	    @Mapping(target = "identityKey",
42	        expression = "java(toIdentityKey(owner))")
43	    @Mapping(target = "checkDigit",
44	        expression = "java(toCheckDigit(owner))")
45	    @Mapping(target = "ageBand",
46	        expression = "java(toAgeBand(owner))")
47	    @Mapping(target = "telephoneDisplay",
48	        expression = "java(toTelephoneDisplay(owner))")
49	    @Mapping(target = "salutation",
50	        expression = "java(toSalutation(owner))")
51	    @Mapping(target = "fiscalYear",
52	        expression = "java(toFiscalYear(owner))")
53	    @Mapping(target = "selfLink",
54	        expression = "java(toSelfLink(owner))")
55	    OwnerDto toOwnerDto(Owner owner);
56	
57	    /**
58	     * Derive an owner's canonical self link: the resource path {@code '/api/owners/<id>'} where
59	     * {@code <id>} is the owner's id. Returns {@code null} when the owner has no id yet (the field is
60	     * then absent from the DTO).
61	     */
62	    default String toSelfLink(Owner owner) {
63	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
64	    }
65	
66	    /**
67	     * The fiscal year that the given date falls in, where the fiscal year starts on 1 July and is
68	     * identified by the calendar year in which it ends. A date on or after 1 July belongs to the
69	     * fiscal year ending in the following calendar year (e.g. 2026-08-01 -&gt; 2027), while a date
70	     * before 1 July belongs to the fiscal year ending in the same calendar year (e.g. 2026-03-01 -&gt;
71	     * 2026). This is the single source of truth for the fiscal year used by both the DTO's
72	     * {@code fiscalYear} and the create endpoint's membership-number year segment.
73	     *
74	     * @param date the date to resolve, on a business day
75	     * @return the calendar year in which that date's fiscal year ends
76	     */
77	    static int fiscalYear(LocalDate date) {
78	        int year = date.getYear();
79	        return date.getMonthValue() >= Month.JULY.getValue() ? year + 1 : year;
80	    }
81	
82	    /**
83	     * Derive an owner's fiscal year from its business-day-adjusted {@code registrationDate},
84	     * formatted {@code 'FY<YY>'} where YY is the last two digits of the fiscal year (see
85	     * {@link #fiscalYear(LocalDate)}), e.g. {@code 'FY27'}. Returns {@code null} when no registration
86	     * date is present (the field is then absent from the DTO).
87	     */
88	    default String toFiscalYear(Owner owner) {
89	        LocalDate registrationDate = owner.getRegistrationDate();
90	        return registrationDate == null ? null : String.format("FY%02d", fiscalYear(registrationDate) % 100);
91	    }
92	
93	    /**
94	     * Derive an owner's salutation: the {@code title}, a single space, and the {@code lastName}
95	     * (e.g. {@code "DR Franklin"}). When no title was supplied (null or blank) the salutation is
96	     * just the last name.
97	     */
98	    default String toSalutation(Owner owner) {
99	        String lastName = owner.getLastName();
100	        String title = owner.getTitle();
101	        if (title == null || title.isBlank()) {
102	            return lastName;
103	        }
104	        return title + " " + lastName;
105	    }
106	
107	    /**
108	     * Derive an owner's age band from the {@code birthDate} relative to the {@code registrationDate}:
109	     * 'MINOR' when under 18, 'ADULT' when 18 to 64, and 'SENIOR' when 65 or older. Returns
110	     * {@code null} when no birth date was supplied (the band is then absent from the DTO). When the
111	     * registration date is missing (e.g. legacy records) the current date is used as the reference.
112	     */
113	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
114	        LocalDate birthDate = owner.getBirthDate();
115	        if (birthDate == null) {
116	            return null;
117	        }
118	        LocalDate reference = owner.getRegistrationDate() != null
119	            ? owner.getRegistrationDate() : LocalDate.now();
120	        int age = Period.between(birthDate, reference).getYears();
121	        if (age < 18) {
122	            return OwnerDto.AgeBandEnum.MINOR;
123	        }
124	        if (age < 65) {
125	            return OwnerDto.AgeBandEnum.ADULT;
126	        }
127	        return OwnerDto.AgeBandEnum.SENIOR;
128	    }
129	
130	    /**
131	     * Format an owner's stored E.164 {@code telephone} for humans: the country code, a space, then the
132	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
133	     * The raw {@code telephone} property is left untouched in E.164 form. Returns the value unchanged
134	     * when it is {@code null} or not in {@code '+'}-prefixed E.164 form.
135	     *
136	     * <p>The recognized dialling codes come from {@link E164PhoneNumbers}, the same table the create
137	     * endpoint validates against, so the two paths cannot diverge. When a number carries no recognized
138	     * code, a two-digit country code is assumed (the most common length).
139	     */
140	    default String toTelephoneDisplay(Owner owner) {
141	        String telephone = owner.getTelephone();
142	        if (telephone == null || !telephone.startsWith("+")) {
143	            return telephone;
144	        }
145	        String digits = telephone.substring(1);
146	        String code = E164PhoneNumbers.countryCode(digits)
147	            .filter(c -> digits.length() > c.length())
148	            .orElse(digits.length() > 2 ? digits.substring(0, 2) : digits);
149	        String national = digits.substring(code.length());
150	        StringBuilder sb = new StringBuilder("+").append(code);
151	        for (int i = 0; i < national.length(); i += 3) {
152	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
153	        }
154	        return sb.toString();
155	    }
156	
157	    /**
158	     * Derive an owner's check digit: a single Luhn check digit (0-9) computed over the digits
159	     * contained in the {@code customerCode}. Non-digit characters (the separators) are ignored.
160	     */
161	    default Integer toCheckDigit(Owner owner) {
162	        String code = owner.getCustomerCode();
163	        if (code == null) {
164	            return null;
165	        }
166	        int sum = 0;
167	        boolean dbl = true;
168	        for (int i = code.length() - 1; i >= 0; i--) {
169	            char c = code.charAt(i);
170	            if (c < '0' || c > '9') {
171	                continue;
172	            }
173	            int d = c - '0';
174	            if (dbl) {
175	                d *= 2;
176	                if (d > 9) {
177	                    d -= 9;
178	                }
179	            }
180	            sum += d;
181	            dbl = !dbl;
182	        }
183	        return (10 - (sum % 10)) % 10;
184	    }
185	
186	    /**
187	     * Derive an owner's duplicate-detection identity key: the normalized E.164 telephone, the
188	     * lower-cased email (empty when none), and the household id (empty when none), joined with
189	     * {@code '|'}. Two owners are duplicates only when their whole identity keys are equal.
190	     *
191	     * <p>This is the single source of truth for the key: it is both returned on the DTO and used by
192	     * the create endpoint's 409 duplicate check, so the value clients see is exactly the value that
193	     * governs rejection. The "email present" rule reuses {@link #hasEmail(Owner)}.
194	     */
195	    default String toIdentityKey(Owner owner) {
196	        String email = hasEmail(owner) ? owner.getEmail() : "";
197	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
198	        return owner.getTelephone() + "|" + email + "|" + household;
199	    }
200	
201	    /**
202	     * Whether the owner has an email address present (non-null and non-empty). Single source of truth
203	     * for the "is an email present" rule shared by the derived fields below.
204	     */
205	    default boolean hasEmail(Owner owner) {
206	        return owner.getEmail() != null && !owner.getEmail().isEmpty();
207	    }
208	
209	    /**
210	     * Derive an owner's preferred contact channel: 'EMAIL' when an email address is present,
211	     * otherwise 'PHONE'.
212	     */
213	    default String toContactPreference(Owner owner) {
214	        return hasEmail(owner) ? "EMAIL" : "PHONE";
215	    }
216	
217	    /**
218	     * Derive an owner's membership points: start at 0; add 2 when an email address is present; add 1
219	     * when the owner has no namesakes (namesakeCount is 0); add 2 when the owner belongs to a
220	     * household of 3 or more (see {@link #hasHouseholdBonus(Owner)}); add 3 when the owner's tenure
221	     * is at least one elapsed fiscal year (see {@link #hasTenureBonus(Owner)}). Because a newly
222	     * created owner has zero tenure it never earns the tenure points, so a new owner with an email
223	     * and no namesakes in a single-member household scores 3 points.
224	     */
225	    default Integer toMembershipPoints(Owner owner) {
226	        int points = 0;
227	        if (hasEmail(owner)) {
228	            points += 2;
229	        }
230	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
231	        if (noNamesakes) {
232	            points += 1;
233	        }
234	        if (hasHouseholdBonus(owner)) {
235	            points += 2;
236	        }
237	        if (hasTenureBonus(owner)) {
238	            points += 3;
239	        }
240	        return points;
241	    }
242	
243	    /**
244	     * Whether the owner belongs to a household of 3 or more members. The household size is the count
245	     * of owners sharing the owner's household id, frozen at creation (see the create endpoint).
246	     * Returns {@code false} when no household size is present (e.g. legacy records).
247	     */
248	    default boolean hasHouseholdBonus(Owner owner) {
249	        return owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
250	    }
251	
252	    /**
253	     * Derive an owner's numeric membership level (1 to 4) from its membership points (see
254	     * {@link #toMembershipPoints(Owner)}): level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6
255	     * or more.
256	     */
257	    default Integer toMembershipLevel(Owner owner) {
258	        int points = toMembershipPoints(owner);
259	        if (points <= 1) {
260	            return 1;
261	        }
262	        if (points <= 3) {
263	            return 2;
264	        }
265	        if (points <= 5) {
266	            return 3;
267	        }
268	        return 4;
269	    }
270	
271	    /**
272	     * Whether the owner's tenure is at least one elapsed fiscal year, i.e. the fiscal year of the
273	     * current date is later than the fiscal year of the {@code registrationDate} (fiscal years start
274	     * on 1 July; see {@link #fiscalYear(LocalDate)}). A brand-new owner (registered in the current
275	     * fiscal year) has zero elapsed fiscal years and so never qualifies. Returns {@code false} when
276	     * no registration date is present.
277	     */
278	    default boolean hasTenureBonus(Owner owner) {
279	        LocalDate registrationDate = owner.getRegistrationDate();
280	        if (registrationDate == null) {
281	            return false;
282	        }
283	        return fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) >= 1;
284	    }
285	
286	    /**
287	     * Fixed city-to-region table used as the fall-back when deriving an owner's locality.
288	     */
289	    Map<String, String> CITY_REGION = Map.of(
290	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
291	
292	    /**
293	     * Fixed region-to-inclusive-postcode-range table used to derive an owner's locality from the
294	     * postcode: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}}
295	     * inclusive.
296	     */
297	    Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
298	        "NSW", new int[] {2000, 2099},
299	        "VIC", new int[] {3000, 3099},
300	        "QLD", new int[] {4000, 4099});
301	
302	    /**
303	     * Derive an owner's locality (region) from the region-and-hash customer code: the {@code <REGION>}
304	     * segment of the {@code customerCode}, i.e. everything before the first {@code '-'}. Since the
305	     * region is baked into the customer code at creation (see the create endpoint), the locality now
306	     * moves with that identity rather than being recomputed from the postcode and city. When an owner
307	     * has no customer code yet (e.g. legacy records), fall back to deriving the region directly via
308	     * {@link #regionOf(Owner)}.
309	     */
310	    default String toLocality(Owner owner) {
311	        String code = owner.getCustomerCode();
312	        if (code != null) {
313	            int dash = code.indexOf('-');
314	            if (dash > 0) {
315	                return code.substring(0, dash);
316	            }
317	        }
318	        return regionOf(owner);
319	    }
320	
321	    /**
322	     * Fixed region-to-IANA-timezone table used to derive an owner's timezone: NSW -> Australia/Sydney,
323	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane.
324	     */
325	    Map<String, String> REGION_TIMEZONE = Map.of(
326	        "NSW", "Australia/Sydney",
327	        "VIC", "Australia/Melbourne",
328	        "QLD", "Australia/Brisbane");
329	
330	    /**
331	     * Derive an owner's IANA timezone name from its locality/region (see {@link #toLocality(Owner)})
332	     * via the fixed {@link #REGION_TIMEZONE} table. Returns {@code null} when the region resolves to no
333	     * entry in the table (e.g. 'UNKNOWN'), so the timezone is then absent from the DTO.
334	     */
335	    default String toTimezone(Owner owner) {
336	        return REGION_TIMEZONE.get(toLocality(owner));
337	    }
338	
339	    /**
340	     * Derive an owner's region, preferring the postcode: when the postcode is present and falls within
341	     * a known region's range (see {@link #REGION_POSTCODE_RANGES}) that region wins. When the postcode
342	     * is absent or in no known range, fall back to the fixed {@link #CITY_REGION} table. Returns
343	     * 'UNKNOWN' when neither the postcode nor the city resolves a region. This is the region baked into
344	     * the {@code <REGION>} segment of a new owner's customer code and, through it, the owner's locality.
345	     */
346	    default String regionOf(Owner owner) {
347	        // Prefer the postcode: the region whose range contains it wins. The logic is kept here (rather
348	        // than in a String -> String helper) because MapStruct would treat such a helper as an implicit
349	        // type conversion and wrongly apply it to other String properties (e.g. telephone).
350	        String postcode = owner.getPostcode();
351	        if (postcode != null) {
352	            try {
353	                int value = Integer.parseInt(postcode.trim());
354	                for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
355	                    int[] range = entry.getValue();
356	                    if (value >= range[0] && value <= range[1]) {
357	                        return entry.getKey();
358	                    }
359	                }
360	            }
361	            catch (NumberFormatException ignored) {
362	                // Non-numeric postcode: fall back to the city table below.
363	            }
364	        }
365	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
366	    }
367	
368	    Owner toOwner(OwnerDto ownerDto);
369	
370	    @Mapping(target = "id", ignore = true)
371	    @Mapping(target = "pets", ignore = true)
372	    Owner toOwner(OwnerFieldsDto ownerDto);
373	
374	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
375	
376	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
377	
378	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
379	        OwnerPageDto ownerPageDto = new OwnerPageDto();
380	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
381	        ownerPageDto.setPage(ownerPage.getNumber());
382	        ownerPageDto.setSize(ownerPage.getSize());
383	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
384	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
385	        return ownerPageDto;
386	    }
