81	
82	    private final HttpServletRequest request;
83	
84	    /** HTTP header carrying the idempotency key for the create-owner endpoint. */
85	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
86	
87	    public OwnerRestControllerV1(ClinicService clinicService,
88	                                 OwnerMapper ownerMapper,
89	                                 PetMapper petMapper,
90	                                 VisitMapper visitMapper,
91	                                 IdempotencyKeyRegistry idempotencyKeyRegistry,
92	                                 HttpServletRequest request) {
93	        this.clinicService = clinicService;
