281	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
282	    @Override
283	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
284	        Owner owner = this.clinicService.findOwnerById(ownerId);
285	        if (owner != null) {
