289	            }
290	        }
291	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
292	    }
293	
294	    /**
295	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where REGION is
296	     * the region derived from the owner's postcode (preferring the postcode, falling back to the
297	     * city table, else {@code 'UNKNOWN'}; see {@link OwnerMapper#regionOf(Owner)}) and HASH8 is the
298	     * first 8 upper-case hex characters of the SHA-256 digest of the owner's normalized E.164
299	     * telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The code carries no
300	     * sequence number, so its base form is a stable function of the owner's region and
301	     * telephone/last-name identity rather than of creation order.
302	     *
303	     * <p>When that computed code already belongs to an existing owner it is de-duplicated by
304	     * appending {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a code no
305	     * existing owner already has; the de-duplicated code is returned.
306	     *
307	     * @param owner the owner being created, with its telephone already normalized to E.164 form
308	     * @return the assigned, collision-free customer code
309	     */
310	    private String customerCodeFor(Owner owner) {
311	        String region = ownerMapper.regionOf(owner);
312	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName()).substring(0, 8);
313	        String baseCode = region + "-" + hash8;
314	        if (!isCustomerCodeInUse(baseCode)) {
315	            return baseCode;
316	        }
317	        int n = 2;
318	        String candidate = baseCode + "-" + n;
319	        while (isCustomerCodeInUse(candidate)) {
320	            n++;
321	            candidate = baseCode + "-" + n;
322	        }
323	        return candidate;
324	    }
325	
326	    /**
327	     * Determines whether any existing owner already carries the given {@code customerCode}, compared
328	     * exactly. Called while assigning a new owner's code so collisions can be de-duplicated.
329	     *
330	     * @param customerCode the candidate customer code to look for
331	     * @return {@code true} if an existing owner already has that customer code
332	     */
333	    private boolean isCustomerCodeInUse(String customerCode) {
334	        for (Owner existing : this.clinicService.findAllOwners()) {
335	            if (customerCode.equals(existing.getCustomerCode())) {
336	                return true;
337	            }
338	        }
339	        return false;
340	    }
341	
342	    /**
343	     * Computes the SHA-256 digest of the UTF-8 bytes of {@code value} and renders it as an
344	     * upper-case hex string.
345	     *
346	     * @param value the string to hash
347	     * @return the full SHA-256 digest as upper-case hex
348	     */
349	    private static String sha256UpperHex(String value) {
350	        try {
351	            byte[] digest = MessageDigest.getInstance("SHA-256")
352	                .digest(value.getBytes(StandardCharsets.UTF_8));
353	            StringBuilder sb = new StringBuilder(digest.length * 2);
354	            for (byte b : digest) {
355	                sb.append(String.format("%02X", b));
356	            }
357	            return sb.toString();
358	        } catch (NoSuchAlgorithmException ex) {
359	            throw new IllegalStateException("SHA-256 not available", ex);
360	        }
361	    }
362	
363	    /**
364	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
365	     * owner's city already contains this many owners.
366	     */
367	    private static final int CITY_CAPACITY = 50;
368	
369	    /**
370	     * The maximum number of owners that may be created on a single day. A create is rejected with
371	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
372	     * {@code registrationDate}.
373	     */
374	    private static final int DAILY_CREATE_LIMIT = 100;
375	
376	    /**
377	     * The number of owners that must already have been created for the current day before a new
378	     * create is flagged with {@code bulkSignupWarning}. The warning is set once more than this many
379	     * owners already carry today's {@code registrationDate}.
380	     */
381	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
382	
383	    /**
384	     * The fixed public holidays that the business-day roll skips. A registration date landing on one
385	     * of these dates is rolled forward, exactly as it is for a weekend day.
386	     */
387	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
388	        LocalDate.parse("2026-01-01"),
389	        LocalDate.parse("2026-01-26"),
390	        LocalDate.parse("2026-04-25"),
391	        LocalDate.parse("2026-12-25"),
392	        LocalDate.parse("2026-12-28"));
393	
394	    /**
395	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday, a
396	     * Sunday or a listed public holiday is advanced one day at a time until it lands on a weekday
397	     * that is not a public holiday, while a date already on a non-holiday weekday is returned
398	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
399	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
400	     * falls on a business day.
401	     *
402	     * @param date the effective registration date
403	     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
404	     */
405	    private static LocalDate rollToBusinessDay(LocalDate date) {
406	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
407	            date = date.plusDays(1);
408	        }
409	        return date;
410	    }
411	
412	    private static boolean isWeekend(LocalDate date) {
413	        return switch (date.getDayOfWeek()) {
414	            case SATURDAY, SUNDAY -> true;
415	            default -> false;
416	        };
417	    }
418	
419	    /**
420	     * Counts the existing owners whose {@code registrationDate} equals the given (already
421	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
422	     * business day. Called before a new owner is saved, so the returned value reflects the number of
423	     * owners created for that day prior to this create.
424	     *
425	     * @param date the adjusted business-day registration date to count against
426	     * @return the number of existing owners registered on that date
427	     */
428	    private int countOwnersRegisteredOn(LocalDate date) {
429	        return (int) this.clinicService.findAllOwners().stream()
430	            .filter(existing -> date.equals(existing.getRegistrationDate()))
431	            .count();
432	    }
433	
434	    /**
435	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
436	     *
437	     * @param city the city to count owners for
438	     * @return the number of existing owners in that city
439	     */
440	    private int countOwnersInCity(String city) {
441	        return (int) this.clinicService.findAllOwners().stream()
442	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
443	            .count();
444	    }
445	
446	    /**
447	     * Builds the membership number for a new owner, formatted {@code '<customerCode>-M<YY>'} where YY is
448	     * the last two digits of the fiscal year (which starts on 1 July) of the business-day-adjusted
449	     * registration date (e.g. {@code 'NSW-1A2B3C4D-M27'}). The fiscal year is derived via
450	     * {@link OwnerMapper#fiscalYear(LocalDate)}, the single source of truth also used by the DTO's
451	     * {@code fiscalYear} field.
452	     *
453	     * @param customerCode     the owner's assigned customer code
454	     * @param registrationDate the owner's business-day-adjusted registration date
455	     * @return the assigned membership number
456	     */
457	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
458	        String yy = String.format("%02d", OwnerMapper.fiscalYear(registrationDate) % 100);
459	        return String.format("%s-M%s", customerCode, yy);
460	    }
461	
462	    /**
463	     * Counts the existing owners that already share the given first name and last name, comparing
464	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
465	     * the number of namesakes that existed prior to this create.
466	     *
467	     * @param firstName the new owner's first name
468	     * @param lastName  the new owner's last name
469	     * @return the number of existing owners with the same first and last name
470	     */
471	    private int countNamesakes(String firstName, String lastName) {
472	        int count = 0;
473	        for (Owner existing : this.clinicService.findAllOwners()) {
474	            if (firstName.equalsIgnoreCase(existing.getFirstName())
475	                && lastName.equalsIgnoreCase(existing.getLastName())) {
476	                count++;
477	            }
478	        }
479	        return count;
480	    }
481	
482	    /**
483	     * Counts the existing owners that already belong to the given household (i.e. that share the
484	     * given {@code householdId}). Called before a new owner is saved, so adding one for the owner
485	     * being created yields the household's total size at the moment of creation. Owners without a
486	     * household id are ignored.
487	     *
488	     * @param householdId the new owner's assigned household id
489	     * @return the number of existing owners already in that household
490	     */
491	    private int countHouseholdMembers(String householdId) {
492	        if (householdId == null) {
493	            return 0;
494	        }
495	        int count = 0;
496	        for (Owner existing : this.clinicService.findAllOwners()) {
497	            if (householdId.equals(existing.getHouseholdId())) {
498	                count++;
499	            }
500	        }
501	        return count;
502	    }
503	
504	    /**
505	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
506	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
507	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
508	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
509	     * string is what gets stored and returned.
510	     *
511	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
512	     *
513	     * <p>Once in E.164 form the national-number length is validated against the country code: a
514	     * {@code +61} (Australia) number must carry exactly 9 national digits and a {@code +1} (NANP)
515	     * number exactly 10 (see {@link E164PhoneNumbers#NATIONAL_LENGTHS}). Country codes without a configured
516	     * rule are accepted on the general 8-to-15 digit length alone.
517	     *
518	     * @param telephone the raw telephone value supplied by the client
519	     * @return the normalized E.164 telephone number
520	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
521	     *                                 valid E.164 number (unexpected characters, not 8 to 15 digits
522	     *                                 after the {@code '+'}, or the wrong national-number length for
523	     *                                 its country code)
524	     */
525	    private static String normalizeTelephone(String telephone) {
526	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
527	        String digits;
528	        if (cleaned.startsWith("+")) {
529	            digits = cleaned.substring(1);
530	        } else {
531	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
532	            digits = "61" + national;
533	        }
534	        if (!digits.matches("[0-9]{8,15}")) {
535	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
536	                "telephone could not be normalized to a valid E.164 number");
537	        }
538	        validateNationalNumberLength(digits);
539	        return "+" + digits;
540	    }
541	
542	    /**
543	     * Validates the national-number length of an E.164 number (its digits, without the leading
544	     * {@code '+'}) against its country code. The longest dialling code that prefixes the number (see
545	     * {@link E164PhoneNumbers#countryCode}) selects the rule; if none is configured the number passes
546	     * (only the general 8-to-15 digit rule applies).
547	     *
548	     * @param digits the E.164 digits without the leading {@code '+'}
549	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the number of national
550	     *                                 digits does not match the country code's required length
551	     */
552	    private static void validateNationalNumberLength(String digits) {
553	        E164PhoneNumbers.countryCode(digits)
554	            .ifPresent(code -> {
555	                int nationalLength = digits.length() - code.length();
556	                int required = E164PhoneNumbers.NATIONAL_LENGTHS.get(code);
557	                if (nationalLength != required) {
558	                    throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
559	                        "telephone must have " + required
560	                            + " national digits for country code +" + code);
561	                }
562	            });
563	    }
564	
565	    /**
566	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
567	     * containing at least one dot, none of the three sections containing whitespace or an
568	     * additional {@code @}.
569	     */
570	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
571	
572	    /**
573	     * Disposable email domains that are not accepted for an owner. An email whose domain is on this
574	     * blocklist is rejected with {@link HttpStatus#BAD_REQUEST}. Entries are lower-case and matched
575	     * case-insensitively against the domain (the part after the {@code @}).
576	     */
577	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
578	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
579	
580	    /**
581	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
582	     * (email is optional). When a value is supplied it must be a syntactically valid address whose
583	     * domain is not on the disposable-domain blocklist; the value is then stored and returned
584	     * lower-cased.
585	     *
586	     * @param email the raw email value supplied by the client, possibly {@code null}
587	     * @return the lower-cased email, or {@code null} when none was supplied
588	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
589	     *                                 is not a syntactically valid address, or its domain is on the
590	     *                                 disposable-domain blocklist
591	     */
592	    private static String normalizeEmail(String email) {
593	        if (email == null) {
594	            return null;
595	        }
596	        if (!EMAIL_PATTERN.matcher(email).matches()) {
597	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
598	                "email must be a syntactically valid address");
599	        }
600	        String normalized = email.toLowerCase(Locale.ROOT);
601	        String domain = normalized.substring(normalized.indexOf('@') + 1);
602	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
603	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
604	                "email domain " + domain + " is not allowed");
605	        }
606	        return normalized;
607	    }
608	
609	    /**
610	     * Fixed region-to-inclusive-postcode-range table. The postcode of an owner whose city maps to a
611	     * known region (via {@link OwnerMapper#CITY_REGION}) must fall within its region's range: NSW
612	     * 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}} inclusive.
613	     */
614	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
615	        "NSW", new int[] {2000, 2099},
616	        "VIC", new int[] {3000, 3099},
617	        "QLD", new int[] {4000, 4099});
618	
619	    /**
620	     * Validates an owner's optional postcode against the city's region. Postcode is validated only
621	     * when present ({@code null} is accepted, keeping the request contract backward-compatible). The
622	     * four-digit format is enforced by request validation; here the value is range-checked: when the
623	     * city maps to a known region (via {@link OwnerMapper#CITY_REGION}) the postcode must fall within
624	     * that region's inclusive range (see {@link #REGION_POSTCODE_RANGES}). A city with no known region
625	     * accepts any four-digit postcode.
626	     *
627	     * @param city     the owner's city
628	     * @param postcode the owner's postcode, possibly {@code null}
629	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a supplied postcode is
630	     *                                 out of range for the city's region
631	     */
632	    private static void validatePostcode(String city, String postcode) {
633	        if (postcode == null) {
634	            return;
635	        }
636	        String region = OwnerMapper.CITY_REGION.get(city);
637	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
638	        if (range == null) {
639	            return;
640	        }
641	        int value = Integer.parseInt(postcode);
642	        if (value < range[0] || value > range[1]) {
643	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
644	                "postcode " + postcode + " is not valid for region " + region);
645	        }
646	    }
647	
648	    /**
649	     * Common street-type abbreviations expanded to their full word during address normalization.
650	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
651	     */
652	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
653	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
654	
655	    /**
656	     * Applies an owner's address, accepting either the structured form (a non-blank
657	     * {@code addressLine1} with an optional {@code addressLine2}) or the flat {@code address} form,
658	     * preferring the structured fields when present. Whichever fields are supplied are normalized
659	     * (see {@link #normalizeAddress(String)}), and the stored flat {@code address} is set to the
660	     * composed value: the normalized {@code addressLine1}, with a single space and the normalized
661	     * {@code addressLine2} appended when an {@code addressLine2} was supplied. When only the flat
662	     * form is supplied, the normalized flat address is stored and both structured lines are cleared.
663	     * This keeps the request contract backward-compatible: an owner that supplied just the flat
664	     * {@code address} (plus city) is still accepted.
665	     *
666	     * @param owner the owner being created or updated, carrying the raw address fields
667	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if neither a non-blank
668	     *                                 {@code addressLine1} nor a non-blank flat {@code address} was
669	     *                                 supplied
670	     */
671	    private static void applyAddress(Owner owner) {
672	        boolean hasStructured = owner.getAddressLine1() != null && !owner.getAddressLine1().isBlank();
673	        boolean hasFlat = owner.getAddress() != null && !owner.getAddress().isBlank();
674	        if (!hasStructured && !hasFlat) {
675	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
676	                "an address must be supplied, either 'addressLine1' or 'address'");
677	        }
678	        if (hasStructured) {
679	            String line1 = normalizeAddress(owner.getAddressLine1());
680	            owner.setAddressLine1(line1);
681	            String composed = line1;
682	            if (owner.getAddressLine2() != null && !owner.getAddressLine2().isBlank()) {
683	                String line2 = normalizeAddress(owner.getAddressLine2());
684	                owner.setAddressLine2(line2);
685	                composed = line1 + " " + line2;
686	            } else {
687	                owner.setAddressLine2(null);
688	            }
689	            owner.setAddress(composed);
690	        } else {
691	            owner.setAddressLine1(null);
692	            owner.setAddressLine2(null);
693	            owner.setAddress(normalizeAddress(owner.getAddress()));
694	        }
695	    }
696	
697	    /**
698	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
699	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
700	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
701	     * {@code AVE -> AVENUE}). This normalized value is what gets stored and returned.
702	     *
703	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
704	     *
705	     * @param address the raw address supplied by the client, possibly {@code null}
706	     * @return the normalized address
707	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
708	     *                                 after normalization (required field)
709	     */
710	    private static String normalizeAddress(String address) {
711	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
712	        if (collapsed.isEmpty()) {
713	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
714	                "address must not be blank");
715	        }
716	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
717	        StringBuilder normalized = new StringBuilder();
718	        for (int i = 0; i < tokens.length; i++) {
719	            if (i > 0) {
720	                normalized.append(' ');
721	            }
722	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
723	        }
724	        return normalized.toString();
725	    }
726	
727	    /**
728	     * Determines whether the given whole identity key already belongs to any owner other than the
729	     * one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g. on
730	     * create). The key is derived in one place — {@link OwnerMapper#toIdentityKey(Owner)}, the same
731	     * method that builds the {@code identityKey} returned on the DTO — so the value governing the
732	     * 409 is exactly the value clients see. Only an exact full-key match counts as a duplicate.
733	     *
734	     * @param identityKey the identity key to look for
735	     * @param excludeId   id of an owner to ignore during the check, or {@code null} for none
736	     * @return {@code true} if another owner already has the same identity key
737	     */
738	    private boolean isIdentityKeyInUse(String identityKey, Integer excludeId) {
739	        for (Owner existing : this.clinicService.findAllOwners()) {
740	            if (existing.isDeleted()) {
741	                continue;
742	            }
743	            if (excludeId != null && excludeId.equals(existing.getId())) {
744	                continue;
745	            }
746	            if (identityKey.equals(ownerMapper.toIdentityKey(existing))) {
747	                return true;
748	            }
749	        }
750	        return false;
751	    }
752	
753	    /**
754	     * Finds the existing owner that the given (not-a-hard-duplicate) new owner is a possible
755	     * (soft) duplicate of: one that shares the new owner's last name (compared case-insensitively)
756	     * and postcode while carrying a <em>different</em> normalized telephone. A hard duplicate
757	     * (identical identity key) has already been rejected with a 409 before this runs, so this
758	     * flags only the softer last-name/postcode overlap. The match with the lowest id is returned
759	     * so the result is deterministic when several owners qualify.
760	     *
761	     * @param owner the new owner being created, with its telephone already normalized
762	     * @return the matching existing owner, or {@code null} when none qualifies
763	     */
764	    private Owner findPossibleDuplicate(Owner owner) {
765	        if (owner.getLastName() == null || owner.getPostcode() == null) {
766	            return null;
767	        }
768	        return this.clinicService.findAllOwners().stream()
769	            .filter(existing -> !existing.isDeleted())
770	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
771	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
772	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
773	            .min(Comparator.comparingInt(Owner::getId))
774	            .orElse(null);
775	    }
776	
777	}
