119	        return this.addressLine1;
120	    }
121	
122	    public void setAddressLine1(String addressLine1) {
123	        this.addressLine1 = addressLine1;
124	    }
125	
126	    public String getAddressLine2() {
127	        return this.addressLine2;
128	    }
129	
